            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            ring = {(y, x) for y in range(y0, y1 + 1) for x in range(x0, x1 + 1)
                    if y in (y0, y1) or x in (x0, x1)}
            if comp == ring:
                interior = [(y, x) for y in range(y0 + 1, y1) for x in range(x0 + 1, x1)]
                v = fill(len(interior))
                for y, x in interior:
                    out[y][x] = v
    return out

def stamp_marker_motif(grid, bg=None, noise=None, anchor=None):
    """Stamp the grid's small multi-color motif centered on every isolated noise dot."""
    from collections import Counter as _C
    bg = bg if bg is not None else background(grid)
    cnt = _C(v for r in grid for v in r)
    cands = [c for c in cnt if c != bg]
    noise = noise if noise is not None else max(cands, key=lambda c: cnt[c])
    ys = [y for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    xs = [x for y, r in enumerate(grid) for x, v in enumerate(r) if v not in (bg, noise)]
    y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
    motif = [row[x0:x1 + 1] for row in grid[y0:y1 + 1]]
    H, W = len(motif), len(motif[0])
    ay, ax = anchor if anchor is not None else ((H - 1) // 2, (W - 1) // 2)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for y in range(h):
        for x in range(w):
            if grid[y][x] == noise:
                for dy in range(H):
                    for dx in range(W):
                        yy, xx = y + dy - ay, x + dx - ax
                        if 0 <= yy < h and 0 <= xx < w:
                            out[yy][xx] = motif[dy][dx]
    return out

def concave_twin_recolor(grid, bg=None):
    """Recolor to the L-stroke color the shape-twin of the component nested in the L's concave corner."""
    bg=bg if bg is not None else background(grid)
    dst,stroke=l_stroke(grid,bg)
    ys=[y for y,x in stroke]; xs=[x for y,x in stroke]
    y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
    cc={c:comps(grid,c) for c in set(v for r in grid for v in r)-{bg}}
    inside=[comp for c,cl in cc.items() if c!=dst for comp in cl
            if all(y0<=y<=y1 and x0<=x<=x1 for y,x in comp) and not (set(comp) & stroke)]
    assert len(inside)==1
    inner=normalize_shape(inside[0])
    groups={}
    for c,cl in cc.items():
        if c==dst: continue
        for comp in cl: groups.setdefault(normalize_shape(comp),[]).append(comp)
    twins=[m for m in groups[inner] if m!=inside[0]]
    assert len(twins)==1
    out=[row[:] for row in grid]
    for y,x in twins[0]: out[y][x]=dst
    return out

from collections import Counter, deque

def intersect_blocks(grid, color=2):
    """Cells non-zero in every patterned block, recolored; a single block maps to itself."""
    bl = [b for grp in pattern_blocks(grid, include_zero=True) for b in grp
          if any(len(set(row)) > 1 for row in b)]
    if len(bl) == 1:
        return [[color if v else 0 for v in row] for row in bl[0]]
    h, w = len(bl[0]), len(bl[0][0])
    return [[color if all(b[i][j] != 0 for b in bl) else 0 for j in range(w)] for i in range(h)]

def shared_color_mark(grid, mark=3):
    """The two blocks split by a full separator line, marked where both blocks show the color they share; that shared color elsewhere."""
    bl = [b for grp in pattern_blocks(grid, include_zero=True) for b in grp]
    A, B = bl[0], bl[1] if len(bl) > 1 else bl[0]
    shared = ({v for r in A for v in r} & {v for r in B for v in r}).pop()
    return [[mark if a == shared and b == shared else shared for a, b in zip(ra, rb)] for ra, rb in zip(A, B)]

def tile_rotations_quadrants(grid):
    """The grid tiled 2x2: top-left as-is, top-right rotated 90 clockwise, bottom-right 180, bottom-left 270."""
    n, w = len(grid), len(grid[0])
    tl = grid
    tr = rotate_cw(grid, 1)
    br = rot180(grid)
    bl = rotate_ccw(grid, 1)
    return vstack(hstack(tl, tr), hstack(bl, br))

def block_count_map(grid, color, include_zero=False):
    """Counts of color in each separator-delimited block, as a grid of counts."""
    return [[count_color(b, color) for b in row] for row in blocks(grid, include_zero)]

def one_color_lines(grid, axis=None):
    """Indices of rows (axis=0) or columns (axis=1) that are a single color throughout; both if axis is None."""
    h, w = len(grid), len(grid[0])
    rows = [i for i in range(h) if len(set(grid[i])) == 1]
    cols = [j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1]
    return (rows, cols) if axis is None else (rows if axis == 0 else cols)

def index_runs(idx):
    """A sorted index list as its contiguous runs."""
    out = []
    for i in idx:
        if out and i == out[-1][-1] + 1: out[-1].append(i)
        else: out.append([i])
    return out

def rotate_ccw(grid, k=1):
    """The grid rotated 90 degrees counter-clockwise k times."""
    return rotate_cw(grid, 4 - (k % 4) if k % 4 else 0) if k % 4 else [r[:] for r in grid]



def fill_h_gaps(grid, fill=2):
    """In each row, recolor to fill every cell lying strictly between two cells of the same non-background color (background = most common color)."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for row in out:
        cols = [j for j, v in enumerate(row) if v != bg]
        for a, b in zip(cols, cols[1:]):
            if all(row[j] == bg for j in range(a + 1, b)):
                for j in range(a + 1, b):
                    row[j] = fill
    return out


def diagonal_bands_tile(grid):
    """Colored diagonal lines (each a band of constant i-j or i+j) extend: the whole grid is tiled by those bands' colors cycling with period = number of colors."""
    cells=[(i,j,v) for i,row in enumerate(grid) for j,v in enumerate(row) if v]
    percolor=sum(1 for c in {v for _,_,v in cells} if len({i-j for i,j,v2 in cells if v2==c})==1)
    percolor2=sum(1 for c in {v for _,_,v in cells} if len({i+j for i,j,v2 in cells if v2==c})==1)
    band=(lambda i,j:i+j) if percolor2>=percolor else (lambda i,j:i-j)
    n=len({v for _,_,v in cells})
    m=next(m for m in range(2,10) if len({band(i,j)%m for i,j,_ in cells})==n)
    seq={}
    for i,j,v in cells: seq[band(i,j)%m]=v
    assert len(seq)==m
    return [[seq[band(i,j)%m] for j in range(len(grid[0]))] for i in range(len(grid))]


def index_bands(n, sep_idx):
    """The contiguous index ranges of 0..n-1 that contain no index in sep_idx."""
    s, out = 0, []
    for i in sorted(sep_idx):
        if i > s: out.append((s, i))
        s = i + 1
    if s < n: out.append((s, n))
    return out

def fill_bands(grid):
    """Every non-background cell is copied to the same relative position in every band delimited by full single-color (non-background) rows and columns."""
    h, w = len(grid), len(grid[0])
    bg = background(grid)
    rseps = {i for i in range(h) if len(set(grid[i])) == 1 and grid[i][0] != bg}
    cseps = {j for j in range(w) if len({r[j] for r in grid}) == 1 and grid[0][j] != bg}
    rb, cb = index_bands(h, rseps), index_bands(w, cseps)
    out = [row[:] for row in grid]
    for i in range(h):
        if i in rseps: continue
        bi = next(k for k, (a, b) in enumerate(rb) if a <= i < b)
        for j in range(w):
            if j in cseps: continue
            v = grid[i][j]
            if v == bg: continue
            bj = next(k for k, (a, b) in enumerate(cb) if a <= j < b)
            for (a, b) in rb:
                for (c, e) in cb:
                    out[a + (i - rb[bi][0])][c + (j - cb[bj][0])] = v
    return out

def frame_border_fill(grid, fill=2):
    """Background cells on the bounding rectangle of the non-background (frame) color become `fill`; a background cell sandwiched vertically or horizontally between two frame cells also becomes `fill`."""
    h,w=len(grid),len(grid[0])
    vals=[v for row in grid for v in row]
    bg=max(set(vals),key=vals.count)
    cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]!=bg]
    if not cells: return [row[:] for row in grid]
    r0,r1=min(i for i,_ in cells),max(i for i,_ in cells)
    c0,c1=min(j for _,j in cells),max(j for _,j in cells)
    out=[row[:] for row in grid]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if out[i][j]==bg and (i in (r0,r1) or j in (c0,c1)
                or (i>r0 and i<r1 and grid[i-1][j]!=bg and grid[i+1][j]!=bg)
                or (j>c0 and j<c1 and grid[i][j-1]!=bg and grid[i][j+1]!=bg)):
                out[i][j]=fill
    return out

def fall_down(grid, steps=1):
    """Every cell falls down `steps` rows within its column; cells pushed past the bottom edge are removed."""
    bg = max({v for row in grid for v in row}, key=lambda v: sum(r.count(v) for r in grid))
    h = len(grid); w = len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and r + steps < h:
                out[r + steps][c] = grid[r][c]
    return out


def recolor_minority_run(row, new):
    """In a single row made of two runs, the shorter run is recolored to new."""
    from itertools import groupby
    runs=[(k,len(list(g))) for k,g in groupby(row)]
    if len(runs)!=2: return row[:]
    out=[]
    for k,g in groupby(row):
        n=len(list(g)); out += [new if k==min(runs,key=lambda r:r[1])[0] else k]*n
    return out

def recolor_minority_rows(grid, new):
    """Every row made of two runs has its shorter run recolored to new; other rows unchanged."""
    return [recolor_minority_run(r,new) if len(set(r))>1 else r[:] for r in grid]


def vertical_period(grid):
    """The smallest p such that every pair of rows holding the non-background color and congruent mod p has one's non-background column set contained in the other's."""
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    c=next(v for v in cnt if v!=bg)
    R=[r for r in range(h) if c in grid[r]]
    cs={r:{j for j in range(w) if grid[r][j]==c} for r in R}
    p=1
    while not all(cs[a]<=cs[b] or cs[b]<=cs[a] for i,a in enumerate(R) for b in R[i+1:] if a%p==b%p):
        p+=1
    return p,bg,c,R,cs

def complete_periodic_noise(grid, new=1):
    """A pattern repeated with a vertical period: background cells inside the union of a stripe's positions become new, and extra pattern-color noise is repainted new at its position shifted into the first period."""
    p,bg,c,R,cs=vertical_period(grid)
    ref={}
    for r in R: ref.setdefault(r%p,set()).update(cs[r])
    out=[row[:] for row in grid]
    for r in R:
        for j in ref[r%p]:
            if out[r][j]==bg: out[r][j]=new
    for r in R:
        for j in cs[r]:
            if j not in ref[r%p] and out[r%p][j]==bg: out[r%p][j]=new
    return out

